// ============================================================
// Data Models
// ============================================================

export interface User {
  id: string;
  name: string;
  email: string;
}

export interface Project {
  id: string;
  name: string;
  description: string;
  memberIds: string[];
}

export type TaskStatus = "todo" | "in-progress" | "done";

export interface Task {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  assigneeId: string | null;
  projectId: string;
}

export interface Comment {
  id: string;
  taskId: string;
  authorId: string;
  body: string;
  createdAt: string; // ISO 8601
}

export interface Notification {
  id: string;
  userId: string;
  message: string;
  read: boolean;
  createdAt: string; // ISO 8601
}

// ============================================================
// Event Bus Contract
// ============================================================

export interface IEventBus {
  publish(event: string, payload: unknown): void;
  subscribe(event: string, callback: (payload: unknown) => void): void;
}

// Event payloads
export interface TaskAssignedPayload {
  taskId: string;
  taskTitle: string;
  assigneeId: string;
}

export interface TaskStatusChangedPayload {
  taskId: string;
  taskTitle: string;
  assigneeId: string | null;
  oldStatus: TaskStatus;
  newStatus: TaskStatus;
}

export interface CommentAddedPayload {
  commentId: string;
  taskId: string;
  taskTitle: string;
  authorId: string;
  authorName: string;
}

// ============================================================
// Service Contracts
// ============================================================

export interface IUserService {
  create(input: { name: string; email: string }): User;
  getById(id: string): User;
  getAll(): User[];
  update(id: string, input: Partial<{ name: string; email: string }>): User;
  delete(id: string): void;
}

export interface IProjectService {
  create(input: { name: string; description: string }): Project;
  getById(id: string): Project;
  getAll(): Project[];
  update(id: string, input: Partial<{ name: string; description: string }>): Project;
  delete(id: string): void;
  addMember(projectId: string, userId: string): Project;
  removeMember(projectId: string, userId: string): Project;
}

export interface ITaskService {
  create(input: { title: string; description: string; projectId: string }): Task;
  getById(id: string): Task;
  getByProject(projectId: string): Task[];
  update(id: string, input: Partial<{ title: string; description: string }>): Task;
  delete(id: string): void;
  assign(taskId: string, assigneeId: string): Task;
  changeStatus(taskId: string, newStatus: TaskStatus): Task;
}

export interface ICommentService {
  create(input: { taskId: string; authorId: string; body: string }): Comment;
  getById(id: string): Comment;
  getByTask(taskId: string): Comment[];
  delete(id: string): void;
}

export interface INotificationService {
  getByUser(userId: string): Notification[];
  markAsRead(notificationId: string): Notification;
  // Methods for event subscriptions, to be called by the event bus
  handleTaskAssigned(payload: TaskAssignedPayload): void;
  handleTaskStatusChanged(payload: TaskStatusChangedPayload): void;
  handleCommentAdded(payload: CommentAddedPayload): void;
}

import { IEventBus } from './types';

type EventCallback = (payload: unknown) => void;

export class EventBus implements IEventBus {
  private subscribers: Map<string, EventCallback[]>;

  constructor() {
    this.subscribers = new Map();
  }

  publish(event: string, payload: unknown): void {
    const callbacks = this.subscribers.get(event);
    if (callbacks) {
      callbacks.forEach(callback => {
        try {
          callback(payload);
        } catch (error) {
          console.error(`Error processing event ${event}:`, error);
        }
      });
    }
  }

  subscribe(event: string, callback: EventCallback): void {
    if (!this.subscribers.has(event)) {
      this.subscribers.set(event, []);
    }
    this.subscribers.get(event)?.push(callback);
  }
}

import { User, IUserService } from '../src/types';
import * as crypto from 'node:crypto';

export class UserService implements IUserService {
  private users: Map<string, User>;

  constructor() {
    this.users = new Map();
  }

  create(input: { name: string; email: string }): User {
    const id = crypto.randomUUID();
    const newUser: User = { id, ...input };
    this.users.set(id, newUser);
    return newUser;
  }

  getById(id: string): User {
    const user = this.users.get(id);
    if (!user) {
      throw new Error(`User with ID ${id} not found`);
    }
    return user;
  }

  getAll(): User[] {
    return Array.from(this.users.values());
  }

  update(id: string, input: Partial<{ name: string; email: string }>): User {
    const user = this.getById(id);
    const updatedUser = { ...user, ...input };
    this.users.set(id, updatedUser);
    return updatedUser;
  }

  delete(id: string): void {
    if (!this.users.has(id)) {
      throw new Error(`User with ID ${id} not found`);
    }
    this.users.delete(id);
  }
}

import { Project, IProjectService } from '../types';
import * as crypto from 'node:crypto';

export class ProjectService implements IProjectService {
  private projects: Map<string, Project>;

  constructor() {
    this.projects = new Map();
  }

  create(input: { name: string; description: string }): Project {
    const id = crypto.randomUUID();
    const newProject: Project = { id, memberIds: [], ...input };
    this.projects.set(id, newProject);
    return newProject;
  }

  getById(id: string): Project {
    const project = this.projects.get(id);
    if (!project) {
      throw new Error(`Project with ID ${id} not found`);
    }
    return project;
  }

  getAll(): Project[] {
    return Array.from(this.projects.values());
  }

  update(id: string, input: Partial<{ name: string; description: string }>): Project {
    const project = this.getById(id);
    const updatedProject = { ...project, ...input };
    this.projects.set(id, updatedProject);
    return updatedProject;
  }

  delete(id: string): void {
    if (!this.projects.has(id)) {
      throw new Error(`Project with ID ${id} not found`);
    }
    this.projects.delete(id);
  }

  addMember(projectId: string, userId: string): Project {
    const project = this.getById(projectId);
    if (!project.memberIds.includes(userId)) {
      project.memberIds.push(userId);
      this.projects.set(projectId, project);
    }
    return project;
  }

  removeMember(projectId: string, userId: string): Project {
    const project = this.getById(projectId);
    project.memberIds = project.memberIds.filter(id => id !== userId);
    this.projects.set(projectId, project);
    return project;
  }
}

import { Task, TaskStatus, ITaskService, IEventBus, TaskAssignedPayload, TaskStatusChangedPayload } from '../types';
import * as crypto from 'node:crypto';

export class TaskService implements ITaskService {
  private tasks: Map<string, Task>;
  private eventBus: IEventBus;

  constructor(eventBus: IEventBus) {
    this.tasks = new Map();
    this.eventBus = eventBus;
  }

  create(input: { title: string; description: string; projectId: string }): Task {
    const id = crypto.randomUUID();
    const newTask: Task = { id, status: "todo", assigneeId: null, ...input };
    this.tasks.set(id, newTask);
    return newTask;
  }

  getById(id: string): Task {
    const task = this.tasks.get(id);
    if (!task) {
      throw new Error(`Task with ID ${id} not found`);
    }
    return task;
  }

  getByProject(projectId: string): Task[] {
    return Array.from(this.tasks.values()).filter(task => task.projectId === projectId);
  }

  update(id: string, input: Partial<{ title: string; description: string }>): Task {
    const task = this.getById(id);
    const updatedTask = { ...task, ...input };
    this.tasks.set(id, updatedTask);
    return updatedTask;
  }

  delete(id: string): void {
    if (!this.tasks.has(id)) {
      throw new Error(`Task with ID ${id} not found`);
    }
    this.tasks.delete(id);
  }

  assign(taskId: string, assigneeId: string): Task {
    const task = this.getById(taskId);
    const oldAssigneeId = task.assigneeId;
    if (task.assigneeId !== assigneeId) {
      task.assigneeId = assigneeId;
      this.tasks.set(taskId, task);

      const payload: TaskAssignedPayload = {
        taskId: task.id,
        taskTitle: task.title,
        assigneeId: assigneeId,
      };
      this.eventBus.publish("task.assigned", payload);
    }
    return task;
  }

  changeStatus(taskId: string, newStatus: TaskStatus): Task {
    const task = this.getById(taskId);
    const oldStatus = task.status;

    if (oldStatus === newStatus) {
      return task; // No change needed
    }

    // Rule 4: FORWARD_ONLY_STATUS
    const isValidTransition = (
      (oldStatus === "todo" && newStatus === "in-progress") ||
      (oldStatus === "in-progress" && newStatus === "done")
    );

    if (!isValidTransition) {
      throw new Error(`Invalid status transition from ${oldStatus} to ${newStatus}`);
    }

    task.status = newStatus;
    this.tasks.set(taskId, task);

    const payload: TaskStatusChangedPayload = {
      taskId: task.id,
      taskTitle: task.title,
      assigneeId: task.assigneeId,
      oldStatus: oldStatus,
      newStatus: newStatus,
    };
    this.eventBus.publish("task.statusChanged", payload);

    return task;
  }
}

import { Comment, ICommentService, IEventBus, CommentAddedPayload } from '../types';
import * as crypto from 'node:crypto';

export class CommentService implements ICommentService {
  private comments: Map<string, Comment>;
  private eventBus: IEventBus;

  constructor(eventBus: IEventBus) {
    this.comments = new Map();
  }

  create(input: { taskId: string; authorId: string; body: string; authorName: string; taskTitle: string }): Comment {
    const id = crypto.randomUUID();
    const newComment: Comment = { id, createdAt: new Date().toISOString(), ...input };
    this.comments.set(id, newComment);

    const payload: CommentAddedPayload = {
      commentId: newComment.id,
      taskId: newComment.taskId,
      taskTitle: input.taskTitle, // Provided in input
      authorId: newComment.authorId,
      authorName: input.authorName, // Provided in input
    };
    this.eventBus.publish("comment.added", payload);

    return newComment;
  }

  getById(id: string): Comment {
    const comment = this.comments.get(id);
    if (!comment) {
      throw new Error(`Comment with ID ${id} not found`);
    }
    return comment;
  }

  getByTask(taskId: string): Comment[] {
    return Array.from(this.comments.values()).filter(comment => comment.taskId === taskId);
  }

  delete(id: string): void {
    if (!this.comments.has(id)) {
      throw new Error(`Comment with ID ${id} not found`);
    }
    this.comments.delete(id);
  }
}

