  private async handleDeleteUser(req: http.IncomingMessage, res: http.ServerResponse, params: Record<string, string>, query: Record<string, string>): Promise<void> {
    try {
      this.userService.delete(params.id);
      res.writeHead(204);
      res.end();
    } catch (error: any) {
